<?php
/** Proof — receivables and payables tools: each answers what the views say, to the cent; the resolver's `q` alone answers a plain list; contact details only to ar.write / ap.write. */
require __DIR__ . '/lib.php';
$W = p4world();
$BEA = 27; $VERA = 26; $CARL = 28;
$num = fn (string $t, int $id): string => (string) one("SELECT number FROM $t WHERE id = :i", ['i' => $id]);
echo "1. Customers\n";
$d = tdata($BEA, 'find_customers', ['q' => 'Acme']);
ok($d === [['customer_id' => $W['acme'], 'name' => 'SMOKE Acme Corp']], 'find_customers q alone: a plain list (customer_id, name)');
$d = tdata($BEA, 'find_customers', ['with_balance' => true]);
ok(array_column($d['customers'], 'customer_id') === [$W['acme']] && same_money($d['customers'][0]['balance_due'], val_as($BEA, "SELECT sum(balance_due) FROM mcp_invoices WHERE customer_id = {$W['acme']} AND status IN ('issued', 'sent', 'viewed', 'partially_paid')")) && $d['customers'][0]['open_invoices'] === 2, 'with_balance: only Acme, 982.50 over two open invoices');
$g = tdata($BEA, 'get_customer', ['customer_id' => $W['acme']]);
ok(count($g['open_invoices']) === 2 && count($g['recent_receipts']) === 1 && count($g['recent_credit_notes']) === 1 && count($g['open_claims']) === 1 && is_array($g['contacts']) && is_array($g['notes']), 'get_customer: open invoices, receipts, credit notes, the open claim; contacts and notes for ar.write');
$gv = tdata($VERA, 'get_customer', ['customer_id' => $W['acme']]);
ok($gv['contacts'] === null && $gv['notes'] === null && $gv['customer']['email'] === null && count($gv['open_invoices']) === 2, 'a Viewer: the same facts, no contacts, notes or address');
ok(tool($BEA, 'get_customer', ['customer_id' => 99999])['error'], 'an unknown customer is a refusal');
$st = tdata($BEA, 'customer_statement', ['customer_id' => $W['acme'], 'from' => '2026-01-01', 'to' => '2026-12-31']);
ok(same_money($st['opening_balance'], '0.00') && count($st['rows']) === 4 && same_money($st['closing_balance'], '962.50') && $st['rows'][0]['kind'] === 'invoice' && same_money($st['rows'][1]['balance'], '1082.50') === false, 'customer_statement: the year opens at 0.00, four rows (invoice, receipt, invoice, credit), closes at 962.50 (' . $st['closing_balance'] . ')');
$st2 = tdata($BEA, 'customer_statement', ['customer_id' => $W['acme'], 'from' => '2026-04-01', 'to' => '2026-12-31']);
ok(same_money($st2['opening_balance'], '1082.50') && count($st2['rows']) === 3 && same_money($st2['closing_balance'], $st['closing_balance']), 'from April: opens at 1,082.50 (the March invoice), the same closing balance');
echo "2. Invoices\n";
$a1 = $num('invoices', $W['inv_a1']);
$d = tdata($BEA, 'find_invoices', ['q' => $a1]);
ok($d === [['invoice_id' => $W['inv_a1'], 'label' => "$a1 — SMOKE Acme Corp — 1082.50 USD"]], 'find_invoices q alone: a number matches whole; label "INV-… — customer — total currency"');
$d = tdata($BEA, 'find_invoices', ['q' => 'Beta', 'status' => ['draft']]);
ok(count($d['invoices']) === 1 && $d['invoices'][0]['invoice_id'] === $W['inv_draft'], 'words of the customer + status draft: the draft invoice');
$dl = tdata($BEA, 'find_invoices', ['q' => 'Beta']);
ok(in_array('Draft #' . $W['inv_draft'] . ' — SMOKE Beta Ltd — 10.00 USD', array_column($dl, 'label'), true), 'a draft\'s label is "Draft #id — customer — total currency"');
$d = tdata($BEA, 'find_invoices', ['overdue' => true]);
ok(array_column($d['invoices'], 'invoice_id') === [$W['inv_a1']] && $d['invoices'][0]['days_overdue'] === (int) val_as($BEA, "SELECT days_overdue FROM mcp_invoices WHERE invoice_id = {$W['inv_a1']}"), 'overdue: only the March invoice, with its days overdue');
$d = tdata($BEA, 'find_invoices', ['customer_id' => $W['acme'], 'from' => '2026-09-01', 'to' => '2026-09-30']);
ok(count($d['invoices']) === 1 && $d['invoices'][0]['invoice_id'] === $W['inv_a2'] && $d['invoices'][0]['open_claims'] === 1 && $d['invoices'][0]['has_live_link'] !== null, 'customer + dates: September\'s invoice, one open claim');
$p = tdata($BEA, 'find_invoices', ['status' => ['paid']]);
ok(array_column($p['invoices'], 'invoice_id') === [$W['inv_b1']] && same_money($p['invoices'][0]['balance_due'], '0.00'), 'status paid: Beta\'s invoice, balance 0.00');
$g = tdata($BEA, 'get_invoice', ['number' => $a1]);
ok(same_money($g['invoice']['total'], '1082.50') && same_money($g['invoice']['tax_total'], '82.50') && count($g['lines']) === 1 && count($g['receipts_applied']) === 1 && same_money($g['receipts_applied'][0]['amount'], '400.00') && str_starts_with((string) $g['invoice']['journal_entry_number'], 'JE-'), 'get_invoice: lines, the 400.00 receipt applied, the entry it posted (' . $g['invoice']['journal_entry_number'] . ')');
ok(!str_contains(json_encode($g), 'token') && !has_key($g, 'token_hash'), 'never a link token');
ok(tool($BEA, 'get_invoice', ['invoice_id' => 99999])['error'] && tool($BEA, 'get_invoice', [])['error'], 'an unknown invoice, or none named, is a refusal');
$ag = tdata($BEA, 'ar_aging', ['as_of' => '2026-10-05']);
$sql = sql_as($BEA, 'SELECT sum(total) AS t, sum(open_invoices) AS n FROM gl_ar_aging(DATE \'2026-10-05\')')[0];
ok(same_money($ag['totals'][0]['total'], $sql['t']) && $ag['totals'][0]['open_invoices'] === (int) $sql['n'] && $ag['totals'][0]['currency'] === 'USD', 'ar_aging: the total per currency equals the function (' . $ag['totals'][0]['total'] . ')');
$one = tdata($BEA, 'ar_aging', ['as_of' => '2026-10-05', 'customer_id' => $W['acme']]);
ok(count($one['customers']) === 1 && count($one['open_invoices']) === 2 && $one['open_invoices'][0]['days_overdue'] > 0, 'one customer: their row and their open invoices bucketed by days overdue');
ok(count(tdata($BEA, 'ar_aging', ['as_of' => '2026-10-05', 'currency' => 'EUR'])['customers']) === 0, 'a currency nobody owes in: empty');
echo "3. Receipts, deposits, credits, claims, tax, days to pay\n";
$rc = tdata($BEA, 'find_receipts', ['unapplied' => true]);
ok(array_column($rc['receipts'], 'receipt_id') === [$W['rcpt_loose']] && same_money($rc['receipts'][0]['unapplied'], '75.00'), 'find_receipts unapplied: Beta\'s 75.00 cash');
$rc = tdata($BEA, 'find_receipts', ['undeposited' => true]);
ok(in_array($W['rcpt_loose'], array_column($rc['receipts'], 'receipt_id'), true) && !in_array($W['rcpt_a'], array_column($rc['receipts'], 'receipt_id'), true), 'undeposited: not the one in a deposit');
$ra = tdata($BEA, 'find_receipts', ['customer_id' => $W['acme']]);
ok(count($ra['receipts']) === 1 && $ra['receipts'][0]['applications'][0]['invoice_number'] === $a1 && same_money($ra['receipts'][0]['applications'][0]['amount'], '400.00') && $ra['receipts'][0]['method'] === 'transfer', 'by customer: the receipt with its application to the invoice');
ok(count(tdata($BEA, 'find_receipts', ['q' => 'SMOKE-CHQ-1'])) === 1 && count(tdata($BEA, 'find_receipts', ['method' => 'cash'])['receipts']) === 1, 'q resolves by reference as a plain list; method filters');
$dp = tdata($BEA, 'find_deposits', ['bank_account_id' => $W['bank']]);
ok($W['deposit'] > 0 && count($dp['deposits']) === 1 && $dp['deposits'][0]['receipts'][0]['receipt_id'] === $W['rcpt_a'] && same_money($dp['deposits'][0]['total'], '400.00'), 'find_deposits: the deposit with its receipt (400.00)');
ok(count(tdata($BEA, 'find_deposits', ['q' => $num('deposits', $W['deposit'])])) === 1, 'q alone resolves a deposit by number');
$cn = tdata($BEA, 'find_credit_notes', ['customer_id' => $W['acme']]);
ok(count($cn['credit_notes']) === 1 && $cn['credit_notes'][0]['status'] === 'issued' && same_money($cn['credit_notes'][0]['balance'], '20.00') && $cn['credit_notes'][0]['applications'] === [] && $cn['credit_notes'][0]['invoice_number'] === $a1, 'find_credit_notes: issued, 20.00 unapplied, raised against the invoice');
$oc = tdata($BEA, 'open_claims', []);
ok(count($oc['claims']) === 1 && $oc['claims'][0]['invoice_id'] === $W['inv_a2'] && same_money($oc['claims'][0]['amount'], '300.00') && count(tdata($BEA, 'open_claims', ['status' => 'confirmed'])['claims']) === 0, 'open_claims: the 300.00 claim; none confirmed');
$tx = tdata($BEA, 'sales_tax', ['from' => '2026-03-01', 'to' => '2026-03-31']);
ok(same_money($tx['tax_total'], '82.50') && same_money($tx['taxable_total'], '1000.00') && $tx['rows'][0]['name'] === 'SMOKE Sales tax 8.25%', 'sales_tax for March: 1,000.00 taxable, 82.50 tax at the 8.25% rate');
$dt = tdata($BEA, 'days_to_pay', ['from' => '2026-01-01', 'to' => '2026-12-31']);
ok($dt['overall']['invoices'] === 1 && count($dt['customers']) === 1 && $dt['customers'][0]['customer_id'] === $W['beta'] && same_money($dt['overall']['average_days'], val_as($BEA, "SELECT round(avg(paid_at::date - issue_date), 1) FROM mcp_invoices WHERE status = 'paid'")), 'days_to_pay: Beta\'s one paid invoice, average days as the view computes');
echo "4. Vendors and bills\n";
$d = tdata($BEA, 'find_vendors', ['q' => 'Hosting']);
ok($d === [['vendor_id' => $W['hosting'], 'name' => 'SMOKE Hosting Co']], 'find_vendors q alone: a plain list (vendor_id, name)');
$d = tdata($BEA, 'find_vendors', ['kind' => 'ai_provider']);
ok(count($d['vendors']) === 2 && array_unique(array_column($d['vendors'], 'kind')) === ['ai_provider'], 'kind=ai_provider: the two providers the AI import made');
$d = tdata($BEA, 'find_vendors', ['with_balance' => true]);
ok(count($d['vendors']) === (int) val_as($BEA, 'SELECT count(*) FROM mcp_vendors WHERE balance_due > 0 AND archived_at IS NULL'), 'with_balance counts what the view holds (' . count($d['vendors']) . ')');
$gv = tdata($BEA, 'get_vendor', ['vendor_id' => $W['hosting']]);
ok(count($gv['open_bills']) === 1 && $gv['open_bills'][0]['bill_id'] === $W['bill_h1'] && is_array($gv['contacts']) && $gv['vendor']['email'] !== null, 'get_vendor: the open bill; contacts and address for ap.write');
$gvv = tdata($VERA, 'get_vendor', ['vendor_id' => $W['hosting']]);
ok($gvv['contacts'] === null && $gvv['notes'] === null && $gvv['vendor']['email'] === null, 'a Viewer: no contacts, notes or address');
$h1 = $num('bills', $W['bill_h1']);
$d = tdata($BEA, 'find_bills', ['q' => 'H-2026-10']);
ok($d === [['bill_id' => $W['bill_h1'], 'label' => "$h1 — SMOKE Hosting Co — 259.80 USD"]], 'find_bills q alone: the vendor\'s reference resolves; label "BILL-… — vendor — total currency"');
ok(count(tdata($BEA, 'find_bills', ['q' => $h1])) === 1, 'and so does the number');
$d = tdata($BEA, 'find_bills', ['status' => ['draft'], 'vendor_id' => $W['hosting']]);
ok(array_column($d['bills'], 'bill_id') === [$W['bill_draft']], 'status draft + vendor: the draft bill');
$d = tdata($BEA, 'find_bills', ['due_within_days' => 7]);
ok(in_array($W['bill_h1'], array_column($d['bills'], 'bill_id'), true) && !in_array($W['bill_draft'], array_column($d['bills'], 'bill_id'), true), 'due_within_days=7: the hosting bill due in three days');
$d = tdata($BEA, 'find_bills', ['overdue' => true]);
ok(count($d['bills']) === (int) val_as($BEA, 'SELECT count(*) FROM mcp_bills WHERE overdue'), 'overdue counts what the view holds');
$d = tdata($BEA, 'find_bills', ['source' => ['ai_usage']]);
ok(count($d['bills']) === 2 && array_unique(array_column($d['bills'], 'source')) === ['ai_usage'], 'source=ai_usage: the two AI bills');
$d = tdata($BEA, 'find_bills', ['no_document' => true]);
ok(count($d['bills']) === (int) val_as($BEA, "SELECT count(*) FROM mcp_bills WHERE NOT has_attachment AND status <> 'void'"), 'no_document: the bills with nothing attached');
$gb = tdata($BEA, 'get_bill', ['bill_id' => $W['bill_h1']]);
ok(same_money($gb['bill']['total'], '259.80') && count($gb['lines']) === 1 && count($gb['notes']) === 1 && str_contains($gb['notes'][0]['body'], 'hosting bill') && str_starts_with((string) $gb['bill']['journal_entry_number'], 'JE-') && $gb['bill']['approved_by_name'] === 'SMOKE Carl', 'get_bill: its line, the note, the entry it posted, who approved it (Carl)');
ok(tool($BEA, 'get_bill', ['number' => 'BILL-999999'])['error'], 'an unknown bill is a refusal');
$aa = tdata($BEA, 'ap_aging', ['as_of' => '2026-10-05']);
$sql = sql_as($BEA, 'SELECT sum(total) AS t, sum(open_bills) AS n FROM gl_ap_aging(DATE \'2026-10-05\')')[0];
ok(same_money($aa['totals'][0]['total'], $sql['t']) && $aa['totals'][0]['open_bills'] === (int) $sql['n'], 'ap_aging: the total per currency equals the function (' . $aa['totals'][0]['total'] . ')');
$du = tdata($BEA, 'ap_due', ['due_within_days' => 7]);
ok(in_array($W['bill_h1'], array_column($du['due'], 'bill_id'), true) && array_column($du['bills_awaiting_approval'], 'bill_id') === [$W['bill_draft']] && array_column($du['payment_runs_open'], 'payment_run_id') === [$W['run']], 'ap_due: the hosting bill is due; the draft bill awaits approval; the run is open');
$sp = tdata($BEA, 'spend', ['from' => '2026-08-01', 'to' => '2026-10-31', 'group_by' => 'vendor']);
ok(same_money(array_sum(array_map(fn ($r) => (float) $r['amount'], $sp['rows'])), val_as($BEA, "SELECT sum(bl.line_subtotal) FROM mcp_bill_lines bl JOIN mcp_bills b ON b.bill_id = bl.bill_id WHERE b.status IN ('approved', 'partially_paid', 'paid') AND b.bill_date BETWEEN '2026-08-01' AND '2026-10-31'")) && count($sp['rows']) >= 3, 'spend by vendor: the total equals the approved bills\' lines');
ok(count(tdata($BEA, 'spend', ['from' => '2026-08-01', 'to' => '2026-10-31', 'group_by' => 'account'])['rows']) >= 2 && count(tdata($BEA, 'spend', ['from' => '2026-08-01', 'to' => '2026-10-31', 'group_by' => 'department'])['rows']) >= 1, 'and by account and by department');
$py = tdata($BEA, 'find_payments', ['vendor_id' => $W['supply']]);
ok(count($py['payments']) === 1 && $py['payments'][0]['status'] === 'recorded' && $py['payments'][0]['cheque_number'] === '7001' && $py['payments'][0]['applications'][0]['bill_id'] === $W['bill_o1'] && same_money($py['payments'][0]['amount'], '85.00'), 'find_payments: the recorded cheque 7001 for 85.00 applied to the bill');
ok(count(tdata($BEA, 'find_payments', ['q' => '7001'])) === 1, 'q resolves by cheque number as a plain list');
$pr = tdata($BEA, 'find_payment_runs', ['status' => 'draft']);
ok(count($pr['payment_runs']) === 1 && $pr['payment_runs'][0]['payment_run_id'] === $W['run'] && count($pr['payment_runs'][0]['payments']) === 1, 'find_payment_runs: the draft run with its payment');
ok(tdata($BEA, 'find_vendor_credits', [])['count'] === 0 && tdata($BEA, 'find_vendor_credits', ['q' => 'VC-1']) === [], 'find_vendor_credits: none yet; a number nobody has resolves to an empty list');
finish();
